void look_0(inout Look k) {
  p_trColour = L0_trColour;
  p_trScrub = L0_trScrub;
  p_trDust = L0_trDust;
  p_trDustAmount = L0_trDustAmount;
  p_trGrit = L0_trGrit;
  p_trRelief = L0_trRelief;
  p_trRough = L0_trRough;
  p_trSheen = L0_trSheen;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float trG = kn(uv * p_trGrit + seed) * kfade(2.0 / p_trGrit);
    float trBlot = kfbm4(uv * 8.0 + seed);
    float trD = clamp(p_trDustAmount * smoothstep(0.35, 0.85, trBlot), 0.0, 1.0);
    k.colour = mix(p_trColour, p_trScrub, 0.4 * smoothstep(0.4, 0.8, kfbm4(uv * 30.0 + seed + 2.0)));
    k.colour = mix(k.colour, p_trDust, trD) * (0.94 + 0.12 * trG);
    k.rough = clamp(p_trRough + 0.06 * trG + 0.06 * trD, 0.0, 1.0);
    k.height = p_trRelief * trG;
    k.sheen = vec3(p_trSheen) * (1.0 - trD);
    k.sheenRough = 0.5;

}

void look_1(inout Look k) {
  p_pmColour = L1_pmColour;
  p_pmPeel = L1_pmPeel;
  p_pmRelief = L1_pmRelief;
  p_pmRough = L1_pmRough;
  p_pmCoat = L1_pmCoat;
  p_pmCoatRough = L1_pmCoatRough;
  p_pmOil = L1_pmOil;
  p_pmOilColour = L1_pmOilColour;
  p_pmOilStreaks = L1_pmOilStreaks;
  p_pmOilRough = L1_pmOilRough;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float pmF = kfade(2.0 / p_pmPeel);
    float pmPeel = (1.0 - kcell(uv * p_pmPeel + seed)) * pmF;
    float pmFine = kn(uv * p_pmPeel * 2.7 + seed + 3.0) * kfade(1.0 / p_pmPeel);
    k.colour = p_pmColour * (0.985 + 0.03 * kfbm4(uv * 2.0 + seed));
    k.rough = clamp(p_pmRough + 0.04 * pmFine, 0.0, 1.0);
    k.height = p_pmRelief * (0.75 * pmPeel + 0.25 * pmFine);
    k.clearcoat = p_pmCoat;
    k.clearcoatRough = p_pmCoatRough;
    if (p_pmOil > 0.0) {
      // runs: noise drawn out along u, fine across v; blotches: a slow fbm; thick where both lie
      float pmRun = kn(vec2(uv.x * p_pmOilStreaks * 0.12, uv.y * p_pmOilStreaks) + seed + 5.0);
      float pmBlot = kfbm(uv * 2.5 + seed + 9.0);
      float pmThick = smoothstep(0.4, 0.8, 0.55 * pmRun + 0.45 * pmBlot);
      float pmO = clamp(p_pmOil * (0.15 + 0.85 * pmThick), 0.0, 1.0);
      vec3 pmOilC = p_pmOilColour * (0.7 + 0.6 * kn(vec2(uv.x * 3.0, uv.y * 40.0) + seed));
      k.colour = mix(k.colour, pmOilC, pmO);
      k.rough = mix(k.rough, p_pmOilRough + 0.5 * (1.0 - pmThick), pmO);
      k.clearcoat = mix(k.clearcoat, 0.0, pmO);
      k.height += p_pmOil * 0.00006 * pmThick;
    }

}

void look_2(inout Look k) {
  p_tpColour = L2_tpColour;
  p_tpFaded = L2_tpFaded;
  p_tpFade = L2_tpFade;
  p_tpGrain = L2_tpGrain;
  p_tpGrainDepth = L2_tpGrainDepth;
  p_tpRough = L2_tpRough;
  p_tpDust = L2_tpDust;
  p_tpDustColour = L2_tpDustColour;
  p_tpDustHeight = L2_tpDustHeight;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float tpSee = kfade(2.0 / p_tpGrain);
    float tpId, tpEdge;
    kvor(uv * p_tpGrain + seed, tpId, tpEdge);
    float tpRim = (1.0 - smoothstep(0.0, 0.18, tpEdge)) * tpSee;
    float tpCell = (kh1(tpId) - 0.5) * tpSee;
    float tpUp = smoothstep(0.2, 0.9, wn.y);
    float tpF = p_tpFade * tpUp * (0.7 + 0.3 * kfbm4(uv * 3.0 + seed));
    k.colour = mix(p_tpColour, p_tpFaded, tpF) * (1.0 + 0.12 * tpCell - 0.15 * tpRim);
    k.rough = clamp(p_tpRough + 0.1 * tpF - 0.08 * tpRim, 0.0, 1.0);
    k.height = p_tpGrainDepth * (0.6 * tpRim + 0.4 * tpCell);
    float tpLow = 1.0 - smoothstep(0.0, p_tpDustHeight, wp.y);
    float tpD = clamp(p_tpDust * tpLow * smoothstep(0.3, 0.8, kfbm(uv * 5.0 + seed + 7.0) + 0.3 * tpLow) * 1.4, 0.0, 1.0);
    k.colour = mix(k.colour, p_tpDustColour, tpD);
    k.rough = mix(k.rough, 0.9, tpD);

}

void look_3(inout Look k) {
  p_gvColour = L3_gvColour;
  p_gvSpangle = L3_gvSpangle;
  p_gvTone = L3_gvTone;
  p_gvRough = L3_gvRough;
  p_gvRoughVar = L3_gvRoughVar;
  p_gvBloom = L3_gvBloom;
  p_gvMetal = L3_gvMetal;
  p_gvRelief = L3_gvRelief;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float gvId, gvE;
    vec2 gvP = uv * p_gvSpangle + seed * 11.0;
    gvP += vec2(kn(uv * 9.0 + seed), kn(uv * 9.0 + seed + 4.0)) * 0.6;
    kvor(gvP, gvId, gvE);
    float gvF = kfade(1.5 / p_gvSpangle);
    // the dendrites: fine lines along the crystal's own angle
    float gvA = gvId * 6.2832;
    vec2 gvDir = vec2(cos(gvA), sin(gvA));
    float gvDen = abs(sin(dot(uv, gvDir) * p_gvSpangle * 40.0 + kn(uv * p_gvSpangle * 6.0) * 3.0));
    gvDen = smoothstep(0.6, 1.0, gvDen) * kfade(0.8 / (p_gvSpangle * 12.0)) * gvF;
    float gvB = smoothstep(0.45, 0.8, kfbm4(uv * 2.5 + seed + 2.0)) * p_gvBloom;
    float gvT = (gvId - 0.5) * 2.0 * p_gvTone * gvF;
    vec3 c = p_gvColour * (1.0 + gvT) * (1.0 - 0.06 * gvDen);
    c = mix(c, vec3(0.56, 0.56, 0.55), gvB);
    k.colour = c;
    k.metal = mix(p_gvMetal, 0.3, gvB);
    k.rough = clamp(p_gvRough + p_gvRoughVar * (kh1(gvId * 17.0) - 0.5) * 2.0 * gvF + 0.08 * gvDen + 0.3 * gvB, 0.05, 1.0);
    k.height = p_gvRelief * (smoothstep(0.03, 0.0, gvE) * gvF + 0.5 * gvDen);

}

void look_4(inout Look k) {
  p_rbColour = L4_rbColour;
  p_rbBloom = L4_rbBloom;
  p_rbBloomAmount = L4_rbBloomAmount;
  p_rbGrit = L4_rbGrit;
  p_rbRelief = L4_rbRelief;
  p_rbRough = L4_rbRough;
  p_rbSheen = L4_rbSheen;
  p_rbSheenRough = L4_rbSheenRough;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float rbG = kn(uv * p_rbGrit + seed) * kfade(2.0 / p_rbGrit);
    float rbP = 1.0 - smoothstep(0.0, 0.25, kcell(uv * p_rbGrit * 0.25 + seed)) ;
    rbP *= kfade(6.0 / p_rbGrit);
    float rbB = smoothstep(0.35, 0.8, kfbm4(uv * 4.0 + seed)) * p_rbBloomAmount;
    k.colour = mix(p_rbColour, p_rbBloom, rbB) * (0.95 + 0.1 * rbG) * (1.0 - 0.3 * rbP);
    k.rough = clamp(p_rbRough + 0.08 * rbB + 0.05 * rbG, 0.0, 1.0);
    k.height = p_rbRelief * (rbG - 0.6 * rbP);
    k.sheen = p_rbSheen;
    k.sheenRough = p_rbSheenRough;

}






Look lookRun(int id) {
  Look k = lookStart();
  switch (id) {
    case 0: look_0(k); break;
    case 1: look_1(k); break;
    case 2: look_2(k); break;
    case 3: look_3(k); break;
    case 4: look_4(k); break;
  }
  if (lookDebug > 0.5) {
